function BigReveal({ value, label, note }) {
  return (
    <div className="text-center py-4">
      <div className="cinzel text-4xl" style={{ color: COLORS.accent }}>{value}</div>
      <p className="text-xs mt-1" style={{ color: COLORS.inkMuted }}>{label}</p>
      {note && <p className="text-xs mt-2 italic" style={{ color: COLORS.evil }}>({note})</p>}
    </div>
  );
}

function SpyCircleView({ players, roleLinks, onClose }) {
  const [wrapRef, wrapWidth] = useContainerWidth(320);
  const size = Math.max(260, Math.min(wrapWidth, 480));
  const radius = size * 0.375;
  const tokenWrap = size * 0.16;
  const tokenSize = size * 0.12;
  const iconSize = tokenSize * 0.9;
  const deadIconSize = size * 0.04;
  const shieldSize = size * 0.0275;
  const statusIconSize = size * 0.0225 * 2 * 0.7;
  const center = size / 2;
  return (
    <div className="fixed inset-0 flex flex-col items-center justify-center p-6" style={{ background: COLORS.shell, zIndex: 55 }}>
      <button onClick={onClose} className="absolute" style={{ top: 20, right: 20, color: COLORS.shellTextMuted }}>
        <X size={28} />
      </button>
      <p className="cinzel text-lg mb-4" style={{ color: COLORS.shellText }}>Grimoire</p>
      <div ref={wrapRef} className="w-full" style={{ maxWidth: 480 }}>
        <div className="relative mx-auto" style={{ width: size, height: size }}>
          <div className="absolute rounded-full" style={{ inset: 0, border: `1px dashed ${COLORS.shellLine}` }} />
          {players.map((p, i) => {
            const shownRole = displayRole(p, roleLinks);
            const butlerChose = players.some((pp) => pp.roleKey === 'butler' && pp.butlerChoiceId === p.id);
            const angle = (i / players.length) * 2 * Math.PI - Math.PI / 2;
            const x = center + radius * Math.cos(angle);
            const y = center + radius * Math.sin(angle);
            return (
              <div key={p.id} className="absolute flex flex-col items-center" style={{ left: x - tokenWrap / 2, top: y - tokenSize / 2, width: tokenWrap }}>
                <div
                  className="rounded-full flex items-center justify-center relative"
                  style={{
                    width: tokenSize,
                    height: tokenSize,
                    background: p.alive ? COLORS.parchment : '#5A5044',
                    border: `2px solid ${p.alive ? COLORS.parchmentLine : '#453F35'}`,
                    opacity: p.alive ? 1 : 0.6,
                  }}
                >
                  {p.alive ? (
                    shownRole.icon ? (
                      <img src={shownRole.icon} alt={shownRole.name} style={{ width: iconSize, height: iconSize, objectFit: 'contain' }} />
                    ) : (
                      <span style={{ fontSize: size * 0.03, color: COLORS.ink }}>{p.name.slice(0, 2).toUpperCase()}</span>
                    )
                  ) : (
                    <Skull size={deadIconSize} style={{ color: COLORS.shellTextMuted }} />
                  )}
                  {p.alive && (p.poisonedBy || p.drunk || p.protectedBy || butlerChose || p.becameImp) && (
                    <div className="absolute flex gap-0.5" style={{ bottom: -4, right: -4 }}>
                      {p.poisonedBy && roleByKey(p.poisonedBy).icon && (
                        <img src={roleByKey(p.poisonedBy).icon} alt="" style={{ width: statusIconSize, height: statusIconSize, objectFit: 'contain', borderRadius: '50%', background: COLORS.parchment, border: `1px solid ${COLORS.evil}` }} />
                      )}
                      {p.drunk && (
                        <img src={ROLE_ICONS.drunk} alt="" style={{ width: statusIconSize, height: statusIconSize, objectFit: 'contain', borderRadius: '50%', background: COLORS.parchment, border: `1px solid ${COLORS.gold}` }} />
                      )}
                      {p.protectedBy && roleByKey(p.protectedBy).icon && (
                        <img src={roleByKey(p.protectedBy).icon} alt="" style={{ width: statusIconSize, height: statusIconSize, objectFit: 'contain', borderRadius: '50%', background: COLORS.parchment, border: `1px solid ${COLORS.good}` }} />
                      )}
                      {butlerChose && (
                        <img src={ROLE_ICONS.butler} alt="" style={{ width: statusIconSize, height: statusIconSize, objectFit: 'contain', borderRadius: '50%', background: COLORS.parchment, border: `1px solid ${COLORS.accent}` }} />
                      )}
                      {p.becameImp && (
                        <img src={ROLE_ICONS.imp} alt="" style={{ width: statusIconSize, height: statusIconSize, objectFit: 'contain', borderRadius: '50%', background: COLORS.parchment, border: `1px solid ${COLORS.evil}` }} />
                      )}
                    </div>
                  )}
                  {!p.alive && p.ghostVoteAvailable && (
                    <div className="absolute" style={{ bottom: -4, right: -4 }}>
                      <Ghost size={shieldSize} style={{ color: COLORS.shellTextMuted }} />
                    </div>
                  )}
                </div>
                <span className="text-xs mt-1 truncate w-full text-center" style={{ color: p.alive ? COLORS.shellText : COLORS.shellTextMuted }}>
                  {p.name}
                </span>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function ConfirmDialog({ title, message, confirmLabel, onConfirm, onCancel }) {
  return (
    <div className="fixed inset-0 flex items-center justify-center p-4" style={{ background: 'rgba(36,16,18,0.85)', zIndex: 55 }}>
      <div className="rounded p-5 text-center" style={{ background: COLORS.parchment, border: `1px solid ${COLORS.evil}`, maxWidth: 'min(90vw, 380px)' }}>
        <p className="cinzel text-lg mb-2" style={{ color: COLORS.evil }}>{title}</p>
        <p className="text-sm mb-5" style={{ color: COLORS.ink }}>{message}</p>
        <div className="flex gap-2">
          <button
            onClick={onCancel}
            className="rounded px-3 py-2 text-xs flex-1"
            style={{ background: COLORS.parchmentDim, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
          >
            Abbrechen
          </button>
          <button
            onClick={onConfirm}
            className="cinzel rounded px-3 py-2 text-xs flex-1"
            style={{ background: COLORS.evil, color: COLORS.accentText }}
          >
            {confirmLabel}
          </button>
        </div>
      </div>
    </div>
  );
}

function PlayerRevealOverlay({ roleName, revealText, onClose }) {
  return (
    <div className="fixed inset-0 flex items-center justify-center p-6" style={{ background: COLORS.shell, zIndex: 50 }}>
      <button onClick={onClose} className="absolute" style={{ top: 20, right: 20, color: COLORS.shellTextMuted }}>
        <X size={28} />
      </button>
      <div className="text-center" style={{ maxWidth: 'min(90vw, 480px)' }}>
        <Moon size={22} style={{ color: COLORS.gold, margin: '0 auto 14px' }} />
        <p className="cinzel text-xl mb-6" style={{ color: COLORS.shellText }}>{roleName}</p>
        <p className="cinzel text-3xl" style={{ color: COLORS.gold, lineHeight: 1.4 }}>{revealText}</p>
      </div>
    </div>
  );
}

function MinionDemonReveal({ kind, players, onBack }) {
  const [viewOpen, setViewOpen] = useState(false);
  const demon = players.find((p) => roleByKey(p.roleKey).team === 'demon');
  const minions = players.filter((p) => roleByKey(p.roleKey).team === 'minion');

  let headerLabel;
  let revealText;
  let explanation;
  if (kind === 'minion_info') {
    headerLabel = 'Schergen';
    revealText = `${minions.length === 1 ? 'Das ist dein Dämon' : 'Das ist euer Dämon'}: ${demon ? demon.name : '–'}`;
    explanation = 'Weckt alle Schergen gemeinsam und zeigt ihnen diese Information.';
  } else {
    headerLabel = 'Dämon';
    const names = minions.map((p) => p.name).join(', ');
    revealText = minions.length === 1 ? `Das ist dein Scherge: ${names}` : `Das sind deine Schergen: ${names}`;
    explanation = 'Weckt den Dämon und zeigt ihm diese Information.';
  }

  return (
    <div className="fixed inset-0 flex items-center justify-center p-4" style={{ background: 'rgba(36,16,18,0.85)', zIndex: 40 }}>
      <div
        className="w-full rounded p-5 relative"
        style={{ maxWidth: 'min(92vw, 640px)', background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}`, maxHeight: '90vh', overflowY: 'auto' }}
      >
        <button onClick={onBack} className="flex items-center gap-1 text-xs mb-6" style={{ color: COLORS.inkMuted }}>
          <ArrowLeft size={14} /> Zurück zum Grimoire
        </button>
        <div className="text-center mb-8">
          <User size={28} style={{ color: COLORS.evil, margin: '0 auto 10px' }} />
          <p className="text-xs tracking-widest" style={{ color: COLORS.inkMuted }}>
            {kind === 'minion_info' ? 'SCHERGEN WACHEN AUF' : 'DÄMON WACHT AUF'}
          </p>
          <h1 className="cinzel text-3xl mt-1" style={{ color: COLORS.evil }}>{headerLabel}</h1>
        </div>
        <p className="text-xs mb-4" style={{ color: COLORS.inkMuted }}>{explanation}</p>
        <button
          onClick={() => setViewOpen(true)}
          className="cinzel rounded px-4 py-2 text-xs flex items-center justify-center gap-2 w-full"
          style={{ background: COLORS.accent, color: COLORS.accentText }}
        >
          <User size={14} /> Spieler-Ansicht zeigen
        </button>
      </div>
      {viewOpen && (
        <PlayerRevealOverlay roleName={headerLabel} revealText={revealText} onClose={() => setViewOpen(false)} />
      )}
    </div>
  );
}

function NightAssistant({ player, players, redHerringId, roleLinks, applyMonkProtection, applyPoison, applyKill, applyButlerChoice, applyImpSelfDestruct, lastExecutedId, nightNumber, onBack }) {
  const isTrueDrunk = player.roleKey === 'drunk';
  const trueRole = roleByKey(player.roleKey);
  const believedRoleKey = isTrueDrunk ? (roleLinks.drunk || {}).believedRoleKey : null;
  const role = believedRoleKey ? roleByKey(believedRoleKey) : trueRole;
  const compromised = Boolean(player.poisonedBy) || player.drunk;
  const [infoMode, setInfoMode] = useState(compromised ? null : 'true');
  const [manualEmpath, setManualEmpath] = useState(null);
  const [manualChef, setManualChef] = useState(null);
  const [ftSelected, setFtSelected] = useState([]);
  const [manualFt, setManualFt] = useState(null);
  const [wwTarget, setWwTarget] = useState('');
  const [wwDecoy, setWwDecoy] = useState('');
  const [actionTarget, setActionTarget] = useState('');
  const [actionDone, setActionDone] = useState(false);
  const [impSpecialMode, setImpSpecialMode] = useState(null);
  const [impNewTarget, setImpNewTarget] = useState('');
  const [mayorSubstituteId, setMayorSubstituteId] = useState('');
  const [resultText, setResultText] = useState('');
  const [recluseAsEvil, setRecluseAsEvil] = useState(null);
  const [showNewImpReveal, setShowNewImpReveal] = useState(false);
  const [spyViewOpen, setSpyViewOpen] = useState(false);
  const [playerViewOpen, setPlayerViewOpen] = useState(false);

  const idx = players.findIndex((p) => p.id === player.id);
  const alive = players.filter((p) => p.alive);

  function toggleFt(id) {
    setFtSelected((prev) => {
      if (prev.includes(id)) return prev.filter((x) => x !== id);
      if (prev.length >= 2) return prev;
      return [...prev, id];
    });
  }

  let body = null;
  let playerReveal = null;

  if (!role.implemented) {
    body = (
      <div>
        {role.description && (
          <p className="text-sm mb-3" style={{ color: COLORS.ink }}>{role.description}</p>
        )}
        <p className="text-xs" style={{ color: COLORS.inkMuted }}>
          Die Fähigkeit ist im Prototyp noch nicht automatisiert, du musst sie von Hand anwenden.
        </p>
      </div>
    );
  } else if (role.key === 'empath') {
    const neighbors = getLivingNeighbors(players, idx);
    const involvesRecluse = neighbors.some((n) => n.roleKey === 'recluse');
    const recluseResolved = !involvesRecluse || recluseAsEvil !== null;
    const trueCount = neighbors.filter((n) => {
      if (n.roleKey === 'recluse') return recluseAsEvil === true;
      return alignmentOf(roleByKey(n.roleKey)) === 'evil';
    }).length;
    const shownCount = infoMode === 'true' ? trueCount : infoMode === 'false' ? manualEmpath : null;
    if (shownCount !== null && recluseResolved) playerReveal = String(shownCount);
    body = (
      <div>
        <p className="text-xs mb-4" style={{ color: COLORS.inkMuted }}>
          Lebende Nachbarn: {neighbors.map((n) => n.name).join(' und ') || '–'}
        </p>
        {involvesRecluse && !recluseResolved ? (
          <RecluseAsk setRecluseAsEvil={setRecluseAsEvil} />
        ) : (
          <>
            {compromised && <CompromiseChoice infoMode={infoMode} setInfoMode={setInfoMode} />}
            {infoMode === 'true' && <BigReveal value={trueCount} label="böse Nachbarn" />}
            {infoMode === 'false' && (
              <div>
                <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Welche Zahl soll stattdessen gezeigt werden?</p>
                <div className="flex gap-2 mb-3">
                  {[0, 1, 2].map((n) => (
                    <button
                      key={n}
                      onClick={() => setManualEmpath(n)}
                      className="cinzel rounded px-4 py-2"
                      style={{
                        background: manualEmpath === n ? COLORS.accent : COLORS.parchmentDim,
                        color: manualEmpath === n ? COLORS.accentText : COLORS.ink,
                        border: `1px solid ${COLORS.parchmentLine}`,
                      }}
                    >
                      {n}
                    </button>
                  ))}
                </div>
                {manualEmpath !== null && (
                  <BigReveal value={manualEmpath} label="böse Nachbarn (falsch)" note={`tatsächlich: ${trueCount}`} />
                )}
              </div>
            )}
          </>
        )}
      </div>
    );
  } else if (role.key === 'chef') {
    const involvesRecluse = players.some((p) => p.roleKey === 'recluse');
    const recluseResolved = !involvesRecluse || recluseAsEvil !== null;
    let trueCount = 0;
    const n = players.length;
    for (let i = 0; i < n; i++) {
      const a = players[i];
      const b = players[(i + 1) % n];
      const alignA = a.roleKey === 'recluse' ? (recluseAsEvil === true ? 'evil' : 'good') : alignmentOf(roleByKey(a.roleKey));
      const alignB = b.roleKey === 'recluse' ? (recluseAsEvil === true ? 'evil' : 'good') : alignmentOf(roleByKey(b.roleKey));
      if (alignA === 'evil' && alignB === 'evil') trueCount++;
    }
    const shownCount = infoMode === 'true' ? trueCount : infoMode === 'false' ? manualChef : null;
    if (shownCount !== null && recluseResolved) playerReveal = String(shownCount);
    body = (
      <div>
        {involvesRecluse && !recluseResolved ? (
          <RecluseAsk setRecluseAsEvil={setRecluseAsEvil} />
        ) : (
          <>
            {compromised && <CompromiseChoice infoMode={infoMode} setInfoMode={setInfoMode} />}
            {infoMode === 'true' && <BigReveal value={trueCount} label="benachbarte böse Paare" />}
            {infoMode === 'false' && (
              <div>
                <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Welche Zahl soll stattdessen gezeigt werden?</p>
                <div className="flex gap-2 mb-3">
                  {[0, 1, 2, 3, 4].map((n2) => (
                    <button
                      key={n2}
                      onClick={() => setManualChef(n2)}
                      className="cinzel rounded px-3 py-2"
                      style={{
                        background: manualChef === n2 ? COLORS.accent : COLORS.parchmentDim,
                        color: manualChef === n2 ? COLORS.accentText : COLORS.ink,
                        border: `1px solid ${COLORS.parchmentLine}`,
                      }}
                    >
                      {n2}
                    </button>
                  ))}
                </div>
                {manualChef !== null && (
                  <BigReveal value={manualChef} label="benachbarte böse Paare (falsch)" note={`tatsächlich: ${trueCount}`} />
                )}
              </div>
            )}
          </>
        )}
      </div>
    );
  } else if (role.key === 'fortuneteller') {
    const selectedPlayers = ftSelected.map((id) => players.find((pp) => pp.id === id)).filter(Boolean);
    const involvesRecluse = selectedPlayers.length === 2 && selectedPlayers.some((p) => p.roleKey === 'recluse');
    const recluseResolved = !involvesRecluse || recluseAsEvil !== null;
    const realDemonSelected = selectedPlayers.some((p) => p.roleKey === 'imp');
    const redHerringSelected = selectedPlayers.some((p) => p.id === redHerringId);
    const recluseTriggers = selectedPlayers.some((p) => p.roleKey === 'recluse' && recluseAsEvil === true);
    const trueResult = ftSelected.length === 2 && (realDemonSelected || redHerringSelected || recluseTriggers) ? 'Ja' : 'Nein';
    const triggeredByRedHerringOnly = trueResult === 'Ja' && redHerringSelected && !realDemonSelected && !recluseTriggers;
    const shownResult = infoMode === 'true' ? trueResult : infoMode === 'false' ? manualFt : null;
    if (ftSelected.length === 2 && shownResult && recluseResolved) playerReveal = shownResult;
    body = (
      <div>
        <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Wähle zwei Spieler zur Überprüfung.</p>
        <div className="flex flex-wrap gap-2 mb-4">
          {alive.map((p) => (
            <button
              key={p.id}
              onClick={() => toggleFt(p.id)}
              className="rounded-full px-3 py-1 text-xs"
              style={{
                background: ftSelected.includes(p.id) ? COLORS.accent : COLORS.parchmentDim,
                color: ftSelected.includes(p.id) ? COLORS.accentText : COLORS.ink,
                border: `1px solid ${COLORS.parchmentLine}`,
              }}
            >
              {p.name}
            </button>
          ))}
        </div>
        {ftSelected.length === 2 && (
          involvesRecluse && !recluseResolved ? (
            <RecluseAsk setRecluseAsEvil={setRecluseAsEvil} />
          ) : (
            <>
              {compromised && <CompromiseChoice infoMode={infoMode} setInfoMode={setInfoMode} />}
              {infoMode === 'true' && (
                <>
                  <BigReveal value={trueResult} label="ist der Dämon dabei" />
                  {triggeredByRedHerringOnly && (
                    <p className="text-xs italic text-center -mt-2 mb-2" style={{ color: COLORS.gold }}>
                      Ausgelöst durch den falschen Dämon (Köder), nicht den echten.
                    </p>
                  )}
                </>
              )}
              {infoMode === 'false' && (
                <div>
                  <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Welche Antwort soll stattdessen gezeigt werden?</p>
                  <div className="flex gap-2 mb-3">
                    {['Ja', 'Nein'].map((v) => (
                      <button
                        key={v}
                        onClick={() => setManualFt(v)}
                        className="cinzel rounded px-4 py-2"
                        style={{
                          background: manualFt === v ? COLORS.accent : COLORS.parchmentDim,
                          color: manualFt === v ? COLORS.accentText : COLORS.ink,
                          border: `1px solid ${COLORS.parchmentLine}`,
                        }}
                      >
                        {v}
                      </button>
                    ))}
                  </div>
                  {manualFt !== null && (
                    <BigReveal value={manualFt} label="ist der Dämon dabei (falsch)" note={`tatsächlich: ${trueResult}`} />
                  )}
                </div>
              )}
            </>
          )
        )}
      </div>
    );
  } else if (role.key === 'washerwoman' || role.key === 'librarian' || role.key === 'investigator') {
    const link = roleLinks[role.key] || {};
    const zeroCase = !link.targetRoleKey && !activeRolesInTeam(players, role.linkTargetTeam);
    const targetRolePlayer = link.targetRoleKey ? players.find((p) => p.roleKey === link.targetRoleKey) : null;
    const decoyRolePlayer = link.decoyRoleKey ? players.find((p) => p.roleKey === link.decoyRoleKey) : null;
    const trueReady = zeroCase || Boolean(targetRolePlayer && decoyRolePlayer);
    const trueReveal = zeroCase
      ? `Keine ${TEAM_LABELS[role.linkTargetTeam]} im Spiel.`
      : (targetRolePlayer && decoyRolePlayer)
        ? `${targetRolePlayer.name} und ${decoyRolePlayer.name}: einer von beiden ist ${roleByKey(link.targetRoleKey).name}.`
        : null;

    const manualAlignment = role.key === 'investigator' ? 'evil' : 'good';
    const manualTargetOptions = alive.filter((p) => alignmentOf(roleByKey(p.roleKey)) === manualAlignment && p.id !== player.id);
    const manualDecoyOptions = alive.filter((p) => String(p.id) !== wwTarget && p.id !== player.id);
    const manualTargetPlayer = players.find((p) => String(p.id) === wwTarget);
    const manualDecoyPlayer = players.find((p) => String(p.id) === wwDecoy);
    const manualReveal = (manualTargetPlayer && manualDecoyPlayer)
      ? `${manualTargetPlayer.name} und ${manualDecoyPlayer.name}: einer von beiden ist ${roleByKey(manualTargetPlayer.roleKey).name}.`
      : null;

    if (infoMode === 'true' && trueReady) {
      playerReveal = trueReveal;
    } else if (infoMode === 'false') {
      playerReveal = manualReveal;
    }

    body = (
      <div>
        {!zeroCase && (
          <p className="text-xs mb-3" style={{ color: COLORS.inkMuted }}>
            Zielrolle und Ablenkungsrolle stammen aus Schritt 3, festgelegt bevor die Namen bekannt waren.
          </p>
        )}
        {compromised && <CompromiseChoice infoMode={infoMode} setInfoMode={setInfoMode} />}
        {infoMode === 'true' && (
          trueReady ? (
            zeroCase ? (
              <BigReveal value="0" label={`keine ${TEAM_LABELS[role.linkTargetTeam]} im Spiel`} />
            ) : (
              <BigReveal
                value={`${targetRolePlayer.name} · ${decoyRolePlayer.name}`}
                label={`einer von beiden ist ${roleByKey(link.targetRoleKey).name}`}
              />
            )
          ) : (
            <p className="text-xs italic" style={{ color: COLORS.evil }}>
              Zu dieser Verknüpfung ist gerade kein passender Spieler zugeteilt.
            </p>
          )
        )}
        {infoMode === 'false' && (
          <div>
            <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>
              Bei falscher Information bist du frei in der Wahl, wähle zwei Spieler.
            </p>
            <div className="flex flex-col gap-3 mb-3">
              <label className="text-xs" style={{ color: COLORS.inkMuted }}>
                Tatsächlicher Treffer
                <select
                  value={wwTarget}
                  onChange={(e) => { setWwTarget(e.target.value); setWwDecoy(''); }}
                  className="block w-full mt-1 rounded px-2 py-2 text-sm"
                  style={{ background: COLORS.parchmentDim, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
                >
                  <option value="">– wählen –</option>
                  {manualTargetOptions.map((p) => (
                    <option key={p.id} value={p.id}>{p.name} ({roleByKey(p.roleKey).name})</option>
                  ))}
                </select>
              </label>
              <label className="text-xs" style={{ color: COLORS.inkMuted }}>
                Zweite Person (Ablenkung)
                <select
                  value={wwDecoy}
                  onChange={(e) => setWwDecoy(e.target.value)}
                  disabled={!wwTarget}
                  className="block w-full mt-1 rounded px-2 py-2 text-sm"
                  style={{ background: COLORS.parchmentDim, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
                >
                  <option value="">– wählen –</option>
                  {manualDecoyOptions.map((p) => <option key={p.id} value={p.id}>{p.name}</option>)}
                </select>
              </label>
            </div>
            {manualReveal && (
              <BigReveal
                value={`${manualTargetPlayer.name} · ${manualDecoyPlayer.name}`}
                label={`einer von beiden ist ${roleByKey(manualTargetPlayer.roleKey).name} (falsch)`}
              />
            )}
          </div>
        )}
      </div>
    );
  } else if (role.key === 'monk' || role.key === 'poisoner' || role.key === 'imp' || role.key === 'butler') {
    const isImp = role.key === 'imp';
    const options = isImp ? players : alive.filter((p) => p.id !== player.id);
    const verbMap = { monk: 'beschützen', poisoner: 'vergiften', imp: 'töten', butler: 'als Vorbild wählen' };
    const doneMap = { monk: 'wurde beschützt', poisoner: 'wurde vergiftet', imp: 'wurde getötet', butler: 'nur wenn diese Person mitstimmt, darfst du auch abstimmen' };
    const verb = verbMap[role.key];
    const succeeds = !compromised || infoMode === 'true';
    const canApply = Boolean(actionTarget) && !actionDone && (!compromised || infoMode);
    const targetPlayer = players.find((p) => String(p.id) === actionTarget);

    function handleApply() {
      if (!actionTarget) return;
      const targetId = Number(actionTarget);
      if (isImp && succeeds) {
        if (targetId === player.id) {
          setImpSpecialMode('selfDestruct');
          return;
        }
        if (targetPlayer && targetPlayer.roleKey === 'mayor' && targetPlayer.alive) {
          setImpSpecialMode('mayor');
          return;
        }
      }
      if (role.key === 'monk') applyMonkProtection(targetId, succeeds);
      else if (role.key === 'poisoner') applyPoison(targetId, succeeds);
      else if (role.key === 'butler') applyButlerChoice(player.id, targetId, succeeds);
      else applyKill(targetId, succeeds);
      if (isImp && succeeds && targetPlayer && !targetPlayer.alive) {
        setResultText(`${targetPlayer.name} war bereits tot. Kein Effekt.`);
      } else {
        setResultText(succeeds && targetPlayer ? `${targetPlayer.name}: ${doneMap[role.key]}` : 'Fähigkeit ist fehlgeschlagen, keine Wirkung');
      }
      setActionDone(true);
    }

    const minionOptions = alive.filter((p) => p.id !== player.id && roleByKey(p.roleKey).team === 'minion');
    const mayorSubOptions = alive.filter((p) => p.id !== Number(actionTarget));

    body = (
      <div>
        {compromised && !actionDone && !impSpecialMode && (
          <CompromiseChoice
            infoMode={infoMode}
            setInfoMode={setInfoMode}
            question="Vergiftet oder betrunken: wirkt die Fähigkeit normal oder schlägt sie fehl?"
            trueLabel="Wirkt normal"
            falseLabel="Schlägt fehl"
          />
        )}
        {actionDone ? (
          <BigReveal value={resultText} label="" />
        ) : impSpecialMode === 'selfDestruct' ? (
          <div>
            <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>
              Der Imp tötet sich selbst. Welcher lebende Scherge wird der neue Imp?
            </p>
            <div className="flex flex-wrap gap-2 mb-3">
              {minionOptions.map((p) => (
                <button
                  key={p.id}
                  onClick={() => setImpNewTarget(String(p.id))}
                  className="rounded-full px-3 py-1 text-xs"
                  style={{
                    background: impNewTarget === String(p.id) ? COLORS.accent : COLORS.parchmentDim,
                    color: impNewTarget === String(p.id) ? COLORS.accentText : COLORS.ink,
                    border: `1px solid ${COLORS.parchmentLine}`,
                  }}
                >
                  {p.name}
                </button>
              ))}
            </div>
            <button
              onClick={() => {
                if (!impNewTarget) return;
                const newImpPlayer = players.find((p) => String(p.id) === impNewTarget);
                applyImpSelfDestruct(player.id, Number(impNewTarget));
                setResultText(newImpPlayer ? `${newImpPlayer.name} ist jetzt der neue Imp, seine Fähigkeit gilt ab der nächsten Nacht.` : 'Neuer Imp bestimmt.');
                setActionDone(true);
              }}
              disabled={!impNewTarget}
              className="cinzel rounded px-4 py-2 text-xs w-full"
              style={{ background: impNewTarget ? COLORS.accent : COLORS.parchmentLine, color: COLORS.accentText, opacity: impNewTarget ? 1 : 0.6 }}
            >
              Bestätigen
            </button>
          </div>
        ) : impSpecialMode === 'mayor' ? (
          <div>
            <p className="text-xs mb-3" style={{ color: COLORS.inkMuted }}>
              Der Bürgermeister würde sterben. Stirbt er wirklich, oder jemand anders an seiner Stelle?
            </p>
            <button
              onClick={() => {
                applyKill(Number(actionTarget), true);
                setResultText('Bürgermeister stirbt.');
                setActionDone(true);
              }}
              className="cinzel rounded px-4 py-2 text-xs w-full mb-3"
              style={{ background: COLORS.accent, color: COLORS.accentText }}
            >
              Bürgermeister stirbt
            </button>
            <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Oder stattdessen:</p>
            <div className="flex flex-wrap gap-2 mb-3">
              {mayorSubOptions.map((p) => (
                <button
                  key={p.id}
                  onClick={() => setMayorSubstituteId(String(p.id))}
                  className="rounded-full px-3 py-1 text-xs"
                  style={{
                    background: mayorSubstituteId === String(p.id) ? COLORS.accent : COLORS.parchmentDim,
                    color: mayorSubstituteId === String(p.id) ? COLORS.accentText : COLORS.ink,
                    border: `1px solid ${COLORS.parchmentLine}`,
                  }}
                >
                  {p.name}
                </button>
              ))}
            </div>
            <button
              onClick={() => {
                if (!mayorSubstituteId) return;
                const sub = players.find((p) => String(p.id) === mayorSubstituteId);
                applyKill(Number(mayorSubstituteId), true);
                setResultText(sub ? `${sub.name} stirbt anstelle des Bürgermeisters.` : 'Ersatzperson stirbt.');
                setActionDone(true);
              }}
              disabled={!mayorSubstituteId}
              className="cinzel rounded px-4 py-2 text-xs w-full"
              style={{ background: mayorSubstituteId ? COLORS.accent : COLORS.parchmentLine, color: COLORS.accentText, opacity: mayorSubstituteId ? 1 : 0.6 }}
            >
              Diese Person stirbt stattdessen
            </button>
          </div>
        ) : (
          <div>
            <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Wen soll {role.name} {verb}?</p>
            <div className="flex flex-wrap gap-2 mb-4">
              {options.map((p) => (
                <button
                  key={p.id}
                  onClick={() => setActionTarget(String(p.id))}
                  className="rounded-full px-3 py-1 text-xs"
                  style={{
                    background: actionTarget === String(p.id) ? COLORS.accent : COLORS.parchmentDim,
                    color: actionTarget === String(p.id) ? COLORS.accentText : COLORS.ink,
                    border: `1px solid ${COLORS.parchmentLine}`,
                  }}
                >
                  {p.name}{isImp && p.id === player.id ? ' (sich selbst)' : ''}{isImp && !p.alive ? ' (bereits tot)' : ''}
                </button>
              ))}
            </div>
            <button
              onClick={handleApply}
              disabled={!canApply}
              className="cinzel rounded px-4 py-2 text-xs w-full"
              style={{ background: canApply ? COLORS.accent : COLORS.parchmentLine, color: COLORS.accentText, opacity: canApply ? 1 : 0.6 }}
            >
              Anwenden
            </button>
          </div>
        )}
      </div>
    );
  } else if (role.key === 'undertaker') {
    const executed = lastExecutedId ? players.find((p) => p.id === lastExecutedId) : null;
    const trueReveal = executed ? roleByKey(executed.roleKey).name : 'Niemand wurde heute hingerichtet.';
    const shownReveal = infoMode === 'true' ? trueReveal : infoMode === 'false' ? null : null;
    body = (
      <div>
        {compromised && <CompromiseChoice infoMode={infoMode} setInfoMode={setInfoMode} />}
        {infoMode === 'true' && <BigReveal value={trueReveal} label={executed ? `Rolle von ${executed.name}` : ''} />}
        {infoMode === 'false' && (
          <div>
            <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Welche Rolle soll stattdessen gezeigt werden?</p>
            <select
              value={manualFt || ''}
              onChange={(e) => setManualFt(e.target.value)}
              className="block w-full mt-1 rounded px-2 py-2 text-sm mb-3"
              style={{ background: COLORS.parchmentDim, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
            >
              <option value="">– wählen –</option>
              {ROLE_CATALOG.map((r) => <option key={r.key} value={r.name}>{r.name}</option>)}
            </select>
            {manualFt && <BigReveal value={manualFt} label="(falsch)" note={`tatsächlich: ${trueReveal}`} />}
          </div>
        )}
      </div>
    );
    if (infoMode === 'true') playerReveal = trueReveal;
    else if (infoMode === 'false' && manualFt) playerReveal = manualFt;
  } else if (role.key === 'ravenkeeper') {
    const justDied = player.diedOnNight === nightNumber && player.deathCause === 'kill';
    if (!justDied) {
      body = (
        <p className="text-sm" style={{ color: COLORS.inkMuted }}>
          Diese Person ist diese Nacht nicht gestorben, die Fähigkeit löst nicht aus.
        </p>
      );
    } else {
      const options = players.filter((p) => p.id !== player.id);
      const targetPlayer = players.find((p) => String(p.id) === actionTarget);
      const trueReveal = targetPlayer ? roleByKey(targetPlayer.roleKey).name : null;
      const shown = infoMode === 'true' ? trueReveal : infoMode === 'false' ? manualFt : null;
      if (shown) playerReveal = shown;
      body = (
        <div>
          <p className="text-xs mb-2" style={{ color: COLORS.inkMuted }}>Wessen Charakter willst du erfahren?</p>
          <div className="flex flex-wrap gap-2 mb-4">
            {options.map((p) => (
              <button
                key={p.id}
                onClick={() => setActionTarget(String(p.id))}
                className="rounded-full px-3 py-1 text-xs"
                style={{
                  background: actionTarget === String(p.id) ? COLORS.accent : COLORS.parchmentDim,
                  color: actionTarget === String(p.id) ? COLORS.accentText : COLORS.ink,
                  border: `1px solid ${COLORS.parchmentLine}`,
                }}
              >
                {p.name}
              </button>
            ))}
          </div>
          {targetPlayer && (
            <>
              {compromised && <CompromiseChoice infoMode={infoMode} setInfoMode={setInfoMode} />}
              {infoMode === 'true' && <BigReveal value={trueReveal} label={`Rolle von ${targetPlayer.name}`} />}
              {infoMode === 'false' && (
                <div>
                  <select
                    value={manualFt || ''}
                    onChange={(e) => setManualFt(e.target.value)}
                    className="block w-full mt-1 rounded px-2 py-2 text-sm mb-3"
                    style={{ background: COLORS.parchmentDim, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
                  >
                    <option value="">– wählen –</option>
                    {ROLE_CATALOG.map((r) => <option key={r.key} value={r.name}>{r.name}</option>)}
                  </select>
                  {manualFt && <BigReveal value={manualFt} label="(falsch)" note={`tatsächlich: ${trueReveal}`} />}
                </div>
              )}
            </>
          )}
        </div>
      );
    }
  } else if (role.key === 'spy') {
    body = (
      <div>
        <p className="text-xs mb-3" style={{ color: COLORS.inkMuted }}>
          Der Spion darf jede Nacht das ganze Grimoire sehen, so wie es der Spielleiter sieht, inklusive aller Status.
        </p>
        <div className="flex flex-col gap-1.5">
          {players.map((p) => {
            const r = roleByKey(p.roleKey);
            const butlerChose = players.some((pp) => pp.roleKey === 'butler' && pp.butlerChoiceId === p.id);
            return (
              <div key={p.id} className="flex items-center gap-2 rounded px-2 py-1.5" style={{ background: COLORS.parchmentDim, opacity: p.alive ? 1 : 0.5 }}>
                {r.icon && <img src={r.icon} alt="" style={{ width: 22, height: 22, objectFit: 'contain' }} />}
                <span className="text-sm" style={{ color: p.alive ? COLORS.ink : COLORS.inkMuted }}>{p.name}</span>
                <span className="text-xs cinzel" style={{ color: alignmentColor(r) }}>{r.name}</span>
                <div className="flex items-center gap-1 ml-auto">
                  {!p.alive && <Skull size={13} style={{ color: COLORS.inkMuted }} />}
                  {!p.alive && p.ghostVoteAvailable && <Ghost size={13} style={{ color: COLORS.inkMuted }} />}
                  {p.poisonedBy && roleByKey(p.poisonedBy).icon && (
                    <img src={roleByKey(p.poisonedBy).icon} alt="vergiftet" style={{ width: 16, height: 16, objectFit: 'contain', borderRadius: '50%', border: `1px solid ${COLORS.evil}` }} />
                  )}
                  {p.drunk && (
                    <img src={ROLE_ICONS.drunk} alt="betrunken" style={{ width: 16, height: 16, objectFit: 'contain', borderRadius: '50%', border: `1px solid ${COLORS.gold}` }} />
                  )}
                  {p.protectedBy && roleByKey(p.protectedBy).icon && (
                    <img src={roleByKey(p.protectedBy).icon} alt="beschützt" style={{ width: 16, height: 16, objectFit: 'contain', borderRadius: '50%', border: `1px solid ${COLORS.good}` }} />
                  )}
                  {butlerChose && (
                    <img src={ROLE_ICONS.butler} alt="Butler-Wahl" style={{ width: 16, height: 16, objectFit: 'contain', borderRadius: '50%', border: `1px solid ${COLORS.accent}` }} />
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="fixed inset-0 flex items-center justify-center p-4" style={{ background: 'rgba(36,16,18,0.85)', zIndex: 40 }}>
      <div
        className="w-full rounded p-5 relative"
        style={{ maxWidth: 'min(92vw, 640px)', background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}`, maxHeight: '90vh', overflowY: 'auto' }}
      >
        <button onClick={onBack} className="flex items-center gap-1 text-xs mb-6" style={{ color: COLORS.inkMuted }}>
          <ArrowLeft size={14} /> Zurück zum Grimoire
        </button>
        <div className="text-center mb-8">
          {role.icon ? (
            <img src={role.icon} alt="" style={{ width: 56, height: 56, margin: '0 auto 10px', objectFit: 'contain' }} />
          ) : (
            <Moon size={28} style={{ color: COLORS.accent, margin: '0 auto 10px' }} />
          )}
          <p className="text-xs tracking-widest" style={{ color: COLORS.inkMuted }}>{player.name.toUpperCase()} WACHT AUF</p>
          <h1 className="cinzel text-3xl mt-1" style={{ color: alignmentColor(role) }}>{role.name}</h1>
        </div>
        {body}
        {playerReveal && (
          <button
            onClick={() => setPlayerViewOpen(true)}
            className="cinzel rounded px-4 py-2 text-xs flex items-center justify-center gap-2 mt-4 w-full"
            style={{ background: COLORS.accent, color: COLORS.accentText }}
          >
            <User size={14} /> Spieler-Ansicht zeigen
          </button>
        )}
        {role.key === 'spy' && (
          <button
            onClick={() => setSpyViewOpen(true)}
            className="cinzel rounded px-4 py-2 text-xs flex items-center justify-center gap-2 mt-4 w-full"
            style={{ background: COLORS.accent, color: COLORS.accentText }}
          >
            <User size={14} /> Spieler-Ansicht zeigen
          </button>
        )}
        {impSpecialMode === 'selfDestruct' && actionDone && (
          <button
            onClick={() => setShowNewImpReveal(true)}
            className="cinzel rounded px-4 py-2 text-xs flex items-center justify-center gap-2 mt-4 w-full"
            style={{ background: COLORS.accent, color: COLORS.accentText }}
          >
            <User size={14} /> Spieler-Ansicht zeigen
          </button>
        )}
      </div>
      {playerViewOpen && (
        <PlayerRevealOverlay roleName={role.name} revealText={playerReveal} onClose={() => setPlayerViewOpen(false)} />
      )}
      {spyViewOpen && (
        <SpyCircleView players={players} roleLinks={roleLinks} onClose={() => setSpyViewOpen(false)} />
      )}
      {showNewImpReveal && (
        <PlayerRevealOverlay roleName="Imp" revealText="Du bist jetzt der Imp." onClose={() => setShowNewImpReveal(false)} />
      )}
    </div>
  );
}

function ModeSelect({ setMode }) {
  return (
    <div className="mx-auto px-5 flex flex-col items-center justify-center" style={{ maxWidth: 'min(96vw, 600px)', minHeight: '100vh' }}>
      <img src={SCRIPT_LOGO} alt="Trouble Brewing" style={{ width: 96, height: 96 }} className="mb-6" />
      <h1 className="cinzel text-3xl mb-2 text-center" style={{ color: COLORS.shellText }}>Blood on the Clocktower</h1>
      <p className="text-sm mb-10 text-center" style={{ color: COLORS.shellTextMuted }}>Companion-Prototyp · Trouble Brewing</p>
      <div className="flex flex-col gap-4 w-full">
        <button
          onClick={() => setMode('st')}
          className="rounded p-5 text-left"
          style={{ background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}` }}
        >
          <p className="cinzel text-lg mb-1" style={{ color: COLORS.accent }}>Ich bin Spielleiter</p>
          <p className="text-sm" style={{ color: COLORS.inkMuted }}>Grimoire, Nachtablauf und Abstimmung für dein Tablet oder deinen PC.</p>
        </button>
        <button
          onClick={() => setMode('player')}
          className="rounded p-5 text-left"
          style={{ background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}` }}
        >
          <p className="cinzel text-lg mb-1" style={{ color: COLORS.accent }}>Ich bin Spieler</p>
          <p className="text-sm" style={{ color: COLORS.inkMuted }}>Rollen-Lexikon zum Nachschlagen auf deinem Handy.</p>
        </button>
      </div>
    </div>
  );
}

const TEAM_ORDER = ['townsfolk', 'outsider', 'minion', 'demon'];

function TeamGroup({ team, roles, dim }) {
  if (roles.length === 0) return null;
  return (
    <div className="flex gap-2 mb-3">
      <div
        className="rounded flex-shrink-0 flex items-center justify-center"
        style={{ width: 24, background: COLORS.accent, writingMode: 'vertical-rl', transform: 'rotate(180deg)' }}
      >
        <span className="cinzel text-xs tracking-widest py-2" style={{ color: COLORS.accentText }}>
          {TEAM_LABELS[team]}
        </span>
      </div>
      <div className="flex-1 flex flex-col gap-2">
        {roles.map((r) => (
          <RoleLexiconRow key={r.key} role={r} dim={dim} />
        ))}
      </div>
    </div>
  );
}

function RoleLexiconRow({ role, dim }) {
  const timing = nightTimingLabel(role);
  return (
    <div
      className="rounded px-3 py-2"
      style={{ background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}`, opacity: dim ? 0.6 : 1 }}
    >
      <div className="flex items-center gap-3 mb-2">
        {role.icon && <img src={role.icon} alt="" style={{ width: 32, height: 32, objectFit: 'contain' }} />}
        <div className="flex-1">
          <span className="cinzel text-sm block" style={{ color: alignmentColor(role) }}>{role.name}</span>
          <span className="text-xs" style={{ color: COLORS.inkMuted }}>
            {TEAM_LABELS[role.team]}{timing ? ` · ${timing}` : ''}
          </span>
        </div>
      </div>
      {role.description && (
        <p className="text-sm" style={{ color: COLORS.ink }}>{role.description}</p>
      )}
    </div>
  );
}

function PlayerLexiconApp({ onExit }) {
  const [lexScreen, setLexScreen] = useState('setup'); // 'setup' | 'lexicon'
  const [lexStep, setLexStep] = useState(1);
  const [lexPool, setLexPool] = useState([]);
  const [lexPlayerCount, setLexPlayerCount] = useState(7);
  const [confirmLexResetOpen, setConfirmLexResetOpen] = useState(false);

  function toggleLexPoolRole(key) {
    setLexPool((prev) => (prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]));
  }
  function selectTBPool() {
    setLexPool(ROLE_CATALOG.map((r) => r.key));
  }
  function setCountClamped(n) {
    setLexPlayerCount(Math.max(5, Math.min(15, n)));
  }

  if (lexScreen === 'setup') {
    return (
      <div style={{ background: COLORS.shell, minHeight: '100vh', fontFamily: "'EB Garamond', Georgia, serif", color: COLORS.shellText }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=EB+Garamond:wght@400;500;600;700&display=swap');
          .cinzel { font-family: 'Cinzel', serif; }
        `}</style>
        <div className="mx-auto px-5 py-8" style={{ maxWidth: 'min(96vw, 700px)' }}>
          <button onClick={onExit} className="text-xs mb-4" style={{ color: COLORS.shellTextMuted }}>← Modus wechseln</button>

          {lexStep === 1 && (
            <div>
              <div className="flex items-center gap-4 mb-5">
                <img src={SCRIPT_LOGO} alt="" style={{ width: 56, height: 56 }} />
                <div>
                  <p className="text-xs tracking-widest" style={{ color: COLORS.gold }}>SCHRITT 1 VON 2</p>
                  <h1 className="cinzel text-2xl mt-1" style={{ color: COLORS.shellText }}>Welche Rollen sind heute im Spiel?</h1>
                </div>
              </div>
              <p className="text-xs mb-4" style={{ color: COLORS.shellTextMuted }}>
                Wähle das Skript, das euer Spielleiter angesagt hat. Bei einem eigenen Skript wählst du die einzelnen Rollen selbst aus.
              </p>
              <button
                onClick={selectTBPool}
                className="text-xs rounded px-3 py-2 mb-4"
                style={{ background: COLORS.accent, color: COLORS.accentText, border: `1px solid ${COLORS.accent}` }}
              >
                Trouble Brewing übernehmen
              </button>
              <div className="flex flex-col gap-2 mb-6">
                {ROLE_CATALOG.map((r) => (
                  <RoleCheckRow key={r.key} role={r} checked={lexPool.includes(r.key)} onToggle={() => toggleLexPoolRole(r.key)} />
                ))}
              </div>
              <WizardNav onNext={() => setLexStep(2)} nextDisabled={lexPool.length === 0} />
            </div>
          )}

          {lexStep === 2 && (
            <div>
              <StepHeader step={2} total={2} title="Wie viele Spieler seid ihr?" />
              <p className="text-xs mb-4" style={{ color: COLORS.shellTextMuted }}>
                Damit zeigt dir das Lexikon auch den passenden Verteilschlüssel.
              </p>
              <div className="flex items-center gap-3 mb-6">
                <button
                  onClick={() => setCountClamped(lexPlayerCount - 1)}
                  className="cinzel rounded flex items-center justify-center"
                  style={{ width: 32, height: 32, background: COLORS.parchment, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
                >
                  −
                </button>
                <span className="cinzel text-2xl" style={{ color: COLORS.shellText, minWidth: 28, textAlign: 'center' }}>{lexPlayerCount}</span>
                <button
                  onClick={() => setCountClamped(lexPlayerCount + 1)}
                  className="cinzel rounded flex items-center justify-center"
                  style={{ width: 32, height: 32, background: COLORS.parchment, color: COLORS.ink, border: `1px solid ${COLORS.parchmentLine}` }}
                >
                  +
                </button>
                <span className="text-xs" style={{ color: COLORS.shellTextMuted }}>Spieler</span>
              </div>
              <WizardNav onBack={() => setLexStep(1)} onNext={() => setLexScreen('lexicon')} nextLabel="Lexikon öffnen" />
            </div>
          )}
        </div>
      </div>
    );
  }

  // lexScreen === 'lexicon'
  const required = getDistribution(lexPlayerCount, lexPool);
  const inPlay = ROLE_CATALOG.filter((r) => lexPool.includes(r.key));
  const notInPlay = ROLE_CATALOG.filter((r) => !lexPool.includes(r.key));

  return (
    <div style={{ background: COLORS.shell, minHeight: '100vh', fontFamily: "'EB Garamond', Georgia, serif", color: COLORS.shellText }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=EB+Garamond:wght@400;500;600;700&display=swap');
        .cinzel { font-family: 'Cinzel', serif; }
      `}</style>
      <div className="mx-auto px-5 py-8" style={{ maxWidth: 'min(96vw, 700px)' }}>
        <div className="flex items-center justify-between mb-2">
          <button onClick={onExit} className="text-xs" style={{ color: COLORS.shellTextMuted }}>← Modus wechseln</button>
          <button onClick={() => setConfirmLexResetOpen(true)} className="text-xs" style={{ color: COLORS.shellTextMuted }}>Neu einrichten</button>
        </div>
        <div className="flex items-center gap-3 mb-4 mt-2">
          <img src={SCRIPT_LOGO} alt="" style={{ width: 40, height: 40 }} />
          <h1 className="cinzel text-2xl" style={{ color: COLORS.shellText }}>Rollen-Lexikon</h1>
        </div>

        <div className="rounded p-3 mb-6" style={{ background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}` }}>
          <p className="text-xs mb-1" style={{ color: COLORS.inkMuted }}>Verteilschlüssel bei {lexPlayerCount} Spielern</p>
          <p className="text-sm cinzel" style={{ color: COLORS.ink }}>
            {countLabel(required.townsfolk, 'Bürger', 'Bürger')} · {countLabel(required.outsider, 'Aussenseiter', 'Aussenseiter')} · {countLabel(required.minion, 'Scherge', 'Schergen')} · {countLabel(required.demon, 'Dämon', 'Dämonen')}
          </p>
        </div>

        <p className="cinzel text-sm mb-2" style={{ color: COLORS.shellText }}>Im Spiel</p>
        <div className="mb-6">
          {TEAM_ORDER.map((t) => (
            <TeamGroup key={t} team={t} roles={inPlay.filter((r) => r.team === t)} />
          ))}
        </div>

        {notInPlay.length > 0 && (
          <>
            <p className="cinzel text-sm mb-2" style={{ color: COLORS.shellTextMuted }}>Nicht im Spiel</p>
            <div className="mb-6">
              {TEAM_ORDER.map((t) => (
                <TeamGroup key={t} team={t} roles={notInPlay.filter((r) => r.team === t)} dim />
              ))}
            </div>
          </>
        )}
      </div>
      {confirmLexResetOpen && (
        <ConfirmDialog
          title="Neu einrichten?"
          message="Die aktuelle Rollenauswahl geht dabei verloren. Diese Aktion kann nicht rückgängig gemacht werden."
          confirmLabel="Ja, neu einrichten"
          onCancel={() => setConfirmLexResetOpen(false)}
          onConfirm={() => { setConfirmLexResetOpen(false); setLexScreen('setup'); setLexStep(1); }}
        />
      )}
    </div>
  );
}

// Einfacher Passwortschutz, rein clientseitig. Das schützt nicht vor jemandem, der wirklich in den
// Quellcode schaut, hält die App aber davor zurück, einfach über einen Link von Fremden gefunden
// und geöffnet zu werden. Passwort hier vor dem Deployment anpassen.
const APP_PASSWORD = '9100';

function PasswordGate({ onSuccess }) {
  const [input, setInput] = useState('');
  const [error, setError] = useState(false);

  function handleSubmit(e) {
    e.preventDefault();
    if (input === APP_PASSWORD) {
      onSuccess();
    } else {
      setError(true);
    }
  }

  return (
    <div style={{ background: COLORS.shell, minHeight: '100vh', display: 'flex', alignItems: 'center', justifyContent: 'center', fontFamily: "'EB Garamond', Georgia, serif", padding: 20 }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=EB+Garamond:wght@400;500;600;700&display=swap');
        .cinzel { font-family: 'Cinzel', serif; }
      `}</style>
      <form
        onSubmit={handleSubmit}
        className="rounded p-6"
        style={{ background: COLORS.parchment, border: `1px solid ${COLORS.parchmentLine}`, maxWidth: 360, width: '100%' }}
      >
        <img src={SCRIPT_LOGO} alt="" style={{ width: 64, height: 64, margin: '0 auto 16px', display: 'block' }} />
        <p className="cinzel text-lg mb-1 text-center" style={{ color: COLORS.accent }}>Blood on the Clocktower</p>
        <p className="text-xs mb-4 text-center" style={{ color: COLORS.inkMuted }}>Passwort eingeben, um fortzufahren</p>
        <input
          type="password"
          value={input}
          onChange={(e) => { setInput(e.target.value); setError(false); }}
          className="block w-full rounded px-3 py-2 text-sm mb-3"
          style={{ background: COLORS.parchmentDim, color: COLORS.ink, border: `1px solid ${error ? COLORS.evil : COLORS.parchmentLine}` }}
          autoFocus
        />
        {error && <p className="text-xs mb-3" style={{ color: COLORS.evil }}>Falsches Passwort.</p>}
        <button type="submit" className="cinzel rounded px-4 py-2 text-sm w-full" style={{ background: COLORS.accent, color: COLORS.accentText }}>
          Bestätigen
        </button>
      </form>
    </div>
  );
}

export default function BotcApp() {
  const [unlocked, setUnlocked] = useState(false);
  const [mode, setMode] = useState('choose'); // 'choose' | 'st' | 'player'

  if (!unlocked) {
    return <PasswordGate onSuccess={() => setUnlocked(true)} />;
  }

  if (mode === 'choose') {
    return (
      <div style={{ background: COLORS.shell, minHeight: '100vh', fontFamily: "'EB Garamond', Georgia, serif", color: COLORS.shellText }}>
        <style>{`
          @import url('https://fonts.googleapis.com/css2?family=Cinzel:wght@500;600;700&family=EB+Garamond:wght@400;500;600;700&display=swap');
          .cinzel { font-family: 'Cinzel', serif; }
        `}</style>
        <ModeSelect setMode={setMode} />
      </div>
    );
  }
  if (mode === 'st') return <StorytellerApp onExit={() => setMode('choose')} />;
  return <PlayerLexiconApp onExit={() => setMode('choose')} />;
}
